// Web Speech API Live Playback Engine
function playVoiceoverSequence() {
  const clips = ["ہفتہ وار سائبر نیوز میں خوش آمدید ۔ میں @ME ہوں، آپ کے لیے گلوبل سائبر اٹیک سرج سے متعلق ایک فوری سیکورٹی بلیٹن لا رہا ہوں ۔","سب سے پہلے: سیکیورٹی محققین عالمی سائبر حملے کے اضافے کے بارے میں ایک اہم مشاورت کی اطلاع دیتے ہیں، جس میں فوری طور پر تخفیف پر زور دیا جاتا ہے ۔ دنیا بھر میں سیکیورٹی ٹیمیں اور تجزیہ کار اس پیشرفت کی نگرانی کر رہے ہیں ۔","ابتدائی رپورٹس ممکنہ صفر دن یا اسناد کے استحصال کے خطرات کی نشاندہی کرتی ہیں جو اختتامی مقامات پر غیر مجاز پس منظر کی نقل و حرکت کی اجازت دیتا ہے ۔","مزید برآں، AI کی مدد سے اسکیننگ اسکرپٹس استحصال کی کھڑکیوں کو تیز کر رہے ہیں، جس سے خودکار پیچ مینجمنٹ ضروری ہو گئی ہے ۔","تنظیموں پر زور دیا جاتا ہے کہ وہ رسائی کے نوشتہ جات کا آڈٹ کریں، کثیر عنصر کی سخت توثیق نافذ کریں، اور فوری طور پر وینڈر سیکیورٹی پیچ لگائیں ۔","باخبر رہیں، محفوظ رہیں، اور یاد رکھیں - سائبر بیداری آپ کا سب سے مضبوط دفاع ہے ۔ مزید اپ ڈیٹس کے لیے @ NajeebCyber کو فالو کریں ۔ میں @ME ہوں، اگلے ہفتے ملیں گے ۔"];
  let index = 0;
  function speakNext() {
    if (index >= clips.length) return;
    const utterance = new SpeechSynthesisUtterance(clips[index]);
    utterance.lang = 'ur-PK';
    utterance.rate = 1.05;
    utterance.onend = () => { index++; speakNext(); };
    window.speechSynthesis.speak(utterance);
  }
  speakNext();
}
